//! Proof that a recovery copy was generated by this project, rather than inferred from its name.

use craft_anything_evidence::{ErrorCode, ToolError, sha256_hex};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::io::{Read as _, Write as _};
use std::path::{Path, PathBuf};

const FORMAT: &str = "craft-anything.feed-backup";
const VERSION: u32 = 1;
const MAX_RECEIPT_BYTES: u64 = 4096;

#[derive(Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Receipt {
    format: String,
    version: u32,
    backup: String,
    length: u64,
    sha256: String,
}

fn valid_name(name: &str) -> bool {
    super::DAMAGED_BACKUP_NAMES.contains(&name)
}

/// Receipt paths stay inside directories already owned by the app. A pre-existing link or
/// non-directory is never followed to store or discover ownership outside the project.
fn directory(root: &Path, create: bool) -> Result<Option<PathBuf>, ToolError> {
    let mut path = root.to_path_buf();
    for name in ["inbox", "feed-backups"] {
        path.push(name);
        let metadata = match std::fs::symlink_metadata(&path) {
            Ok(metadata) => metadata,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound && !create => return Ok(None),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                match std::fs::create_dir(&path) {
                    Ok(()) => craft_anything_platform::fs::set_private_dir(&path)?,
                    Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
                    Err(error) => return Err(ToolError::io(path.display(), error)),
                }
                std::fs::symlink_metadata(&path).map_err(|error| ToolError::io(path.display(), error))?
            }
            Err(error) => return Err(ToolError::io(path.display(), error)),
        };
        if !metadata.is_dir() || metadata.file_type().is_symlink() {
            if !create {
                return Ok(None);
            }
            return Err(ToolError::invalid(format!("{} isn't a regular recovery-record folder.", path.display()))
                .with_remediation("Keep the existing entry in a safe location and restore the project's inbox folder before retrying."));
        }
    }
    Ok(Some(path))
}

fn read_receipt(path: &Path, name: &str) -> Result<Option<Receipt>, ToolError> {
    match std::fs::symlink_metadata(path) {
        Ok(metadata) if metadata.is_file() && !metadata.file_type().is_symlink() => {}
        Ok(_) => return Ok(None),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(ToolError::io(path.display(), error)),
    }
    let bytes = match craft_anything_platform::fs::read_file_capped(path, MAX_RECEIPT_BYTES) {
        Ok(bytes) => bytes,
        Err(error) if matches!(error.code, ErrorCode::NotFound | ErrorCode::OverLimit) => return Ok(None),
        Err(error) => return Err(error),
    };
    let Ok(receipt) = serde_json::from_slice::<Receipt>(&bytes) else { return Ok(None) };
    Ok((receipt.format == FORMAT
        && receipt.version == VERSION
        && receipt.backup == name
        && valid_name(name)
        && receipt.sha256.len() == 64
        && receipt.sha256.bytes().all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)))
    .then_some(receipt))
}

fn matches_backup(root: &Path, receipt: &Receipt) -> Result<bool, ToolError> {
    let path = root.join(&receipt.backup);
    let before = match std::fs::symlink_metadata(&path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(error) => return Err(ToolError::io(path.display(), error)),
    };
    if !before.is_file() || before.file_type().is_symlink() || before.len() != receipt.length {
        return Ok(false);
    }
    let (mut file, opened) = craft_anything_platform::fs::open_regular_file(&path)?;
    if opened.len() != receipt.length {
        return Ok(false);
    }
    // Bound the read to the recorded size so a growing file cannot keep deletion waiting.
    let mut reader = (&mut file).take(receipt.length);
    let mut length = 0u64;
    let mut hash = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let count = reader.read(&mut buffer).map_err(|error| ToolError::io(path.display(), error))?;
        if count == 0 {
            break;
        }
        length = length.saturating_add(count as u64);
        hash.update(buffer.get(..count).ok_or_else(|| ToolError::internal("A recovery-copy read exceeded its buffer."))?);
    }
    let after = match std::fs::symlink_metadata(&path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(error) => return Err(ToolError::io(path.display(), error)),
    };
    Ok(after.is_file()
        && !after.file_type().is_symlink()
        && after.len() == receipt.length
        && before.modified().ok() == after.modified().ok()
        && length == receipt.length
        && hex::encode(hash.finalize()) == receipt.sha256)
}

/// Record a newly created, complete recovery copy. Per-copy receipts avoid a shared registry
/// update. An existing identical receipt is harmless; any other existing entry is left intact.
pub(super) fn record(root: &Path, backup: &Path, bytes: &[u8]) -> Result<(), ToolError> {
    let name =
        backup.file_name().and_then(|name| name.to_str()).filter(|name| valid_name(name)).ok_or_else(|| ToolError::invalid("Unknown recovery-copy name."))?;
    if backup != root.join(name).as_path() {
        return Err(ToolError::invalid("A recovery copy must be beside the project's conversation."));
    }
    let receipt = Receipt {
        format: FORMAT.into(),
        version: VERSION,
        backup: name.into(),
        length: u64::try_from(bytes.len()).map_err(|_| ToolError::new(ErrorCode::OverLimit, "The recovery copy is too large to record."))?,
        sha256: sha256_hex(bytes),
    };
    if !matches_backup(root, &receipt)? {
        return Err(ToolError::new(ErrorCode::FileChanged, "The recovery copy changed before it could be recorded.")
            .with_remediation("Reopen the project before retrying. The original conversation is unchanged."));
    }
    let directory = directory(root, true)?.ok_or_else(|| ToolError::internal("The recovery-record folder wasn't created."))?;
    let path = directory.join(format!("{name}.json"));
    let json = serde_json::to_vec(&receipt).map_err(|error| ToolError::internal(error.to_string()))?;
    let mut options = std::fs::OpenOptions::new();
    options.write(true).create_new(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.mode(0o600);
    }
    let mut file = match options.open(&path) {
        Ok(file) => file,
        Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
            if read_receipt(&path, name)?.as_ref() == Some(&receipt) {
                return Ok(());
            }
            return Err(ToolError::new(ErrorCode::FileChanged, format!("The existing recovery record at {} cannot be replaced.", path.display()))
                .with_remediation("Move the existing recovery record to a safe location, then retry. The original conversation is unchanged."));
        }
        Err(error) => return Err(ToolError::io(path.display(), error)),
    };
    let written = file.write_all(&json).and_then(|()| file.sync_all());
    drop(file);
    if let Err(error) = written {
        let _ = std::fs::remove_file(&path);
        return Err(ToolError::io(path.display(), error));
    }
    Ok(())
}

/// Return only regular, unchanged recovery files with a recognized receipt for this exact name.
/// Missing, malformed or newer receipts establish no ownership and leave legacy files alone.
pub(crate) fn owned_backups(root: &Path) -> Result<Vec<PathBuf>, ToolError> {
    let Some(directory) = directory(root, false)? else { return Ok(Vec::new()) };
    let mut owned = Vec::new();
    for name in super::DAMAGED_BACKUP_NAMES {
        if let Some(receipt) = read_receipt(&directory.join(format!("{name}.json")), name)?
            && matches_backup(root, &receipt)?
        {
            owned.push(root.join(name));
        }
    }
    Ok(owned)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn receipts_belong_to_one_unchanged_regular_backup() {
        let directory = tempfile::tempdir().unwrap();
        let backup = directory.path().join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        record(directory.path(), &backup, b"original").unwrap();
        record(directory.path(), &backup, b"original").unwrap();
        assert_eq!(owned_backups(directory.path()).unwrap().as_slice(), std::slice::from_ref(&backup));

        std::fs::write(&backup, b"personal").unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty(), "the same length doesn't establish ownership of new content");
        std::fs::remove_file(&backup).unwrap();
        std::fs::create_dir(&backup).unwrap();
        std::fs::write(backup.join("notes.txt"), "Keep this directory").unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty(), "a directory can never be a generated recovery file");
    }

    #[test]
    fn unknown_receipts_are_preserved_and_never_authorize_deletion() {
        let directory = tempfile::tempdir().unwrap();
        let backup = directory.path().join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        record(directory.path(), &backup, b"original").unwrap();
        let path = directory.path().join("inbox/feed-backups/feed.json.broken.json");
        let original: serde_json::Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        let cases = [("version", serde_json::json!(99)), ("format", serde_json::json!("personal-data")), ("backup", serde_json::json!("../personal-file"))];
        for (field, value) in cases {
            let mut changed = original.clone();
            changed[field] = value;
            let bytes = serde_json::to_vec(&changed).unwrap();
            std::fs::write(&path, &bytes).unwrap();
            assert!(owned_backups(directory.path()).unwrap().is_empty(), "{field}");
            assert!(record(directory.path(), &backup, b"original").is_err(), "{field}");
            assert_eq!(std::fs::read(&path).unwrap(), bytes, "{field}: the unknown record is not overwritten");
        }
        std::fs::write(&path, b"unreadable receipt").unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty());
        assert!(record(directory.path(), &backup, b"original").is_err());
        assert_eq!(std::fs::read(&path).unwrap(), b"unreadable receipt");
    }

    #[test]
    fn concurrent_copies_keep_separate_receipts() {
        let directory = tempfile::tempdir().unwrap();
        std::thread::scope(|scope| {
            let writers: Vec<_> = ["feed.json.broken", "feed.json.broken.1"]
                .into_iter()
                .map(|name| {
                    let root = directory.path();
                    scope.spawn(move || {
                        let backup = root.join(name);
                        std::fs::write(&backup, name.as_bytes()).unwrap();
                        record(root, &backup, name.as_bytes()).unwrap();
                    })
                })
                .collect();
            for writer in writers {
                writer.join().unwrap();
            }
        });
        assert_eq!(owned_backups(directory.path()).unwrap().len(), 2);
    }

    #[test]
    fn a_failed_receipt_keeps_the_original_conversation() {
        use crate::workspace::{TargetRef, Workspace};
        let directory = tempfile::tempdir().unwrap();
        let ws = Workspace::create(directory.path(), "Site", "A website", TargetRef::None).unwrap();
        let records = ws.root.join("inbox/feed-backups");
        std::fs::create_dir_all(&records).unwrap();
        let path = records.join("feed.json.broken.json");
        let future = br#"{"format":"craft-anything.feed-backup","version":99,"backup":"feed.json.broken","future":true}"#;
        std::fs::write(&path, future).unwrap();
        let source = ws.root.join(crate::feed::FEED_FILE);
        std::fs::write(&source, b"damaged conversation").unwrap();
        let mut feed = crate::feed::load(&ws);

        assert!(crate::feed::save(&ws.root, &mut feed).is_err());

        assert_eq!(std::fs::read(&source).unwrap(), b"damaged conversation");
        assert_eq!(std::fs::read(&path).unwrap(), future);
        assert!(!ws.root.join("feed.json.broken").exists(), "the unsuccessful new copy is cleaned up");
    }

    #[cfg(unix)]
    #[test]
    fn receipts_do_not_follow_backup_or_receipt_links() {
        use std::os::unix::fs::symlink;
        let directory = tempfile::tempdir().unwrap();
        let backup = directory.path().join("feed.json.broken");
        std::fs::write(&backup, b"original").unwrap();
        record(directory.path(), &backup, b"original").unwrap();
        let personal = directory.path().join("personal");
        std::fs::write(&personal, b"original").unwrap();
        std::fs::remove_file(&backup).unwrap();
        symlink(&personal, &backup).unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty());
        std::fs::remove_file(&backup).unwrap();
        std::fs::write(&backup, b"original").unwrap();

        let path = directory.path().join("inbox/feed-backups/feed.json.broken.json");
        let saved = directory.path().join("personal-receipt.json");
        std::fs::rename(&path, &saved).unwrap();
        symlink(&saved, &path).unwrap();
        let original = std::fs::read(&saved).unwrap();
        assert!(owned_backups(directory.path()).unwrap().is_empty());
        assert!(record(directory.path(), &backup, b"original").is_err());
        assert_eq!(std::fs::read(&saved).unwrap(), original);
    }
}
